// 1. Validate Configuration
if (sh_config.max_hold_cycles < 1 || sh_config.max_hold_cycles > 20) {
    sh_state.mode = SH_FAULT;
    sh_state.dropouts = 0;
    sh_state.last_q_bi.w = 1.0;
    sh_state.last_q_bi.x = 0.0;
    sh_state.last_q_bi.y = 0.0;
    sh_state.last_q_bi.z = 0.0;

    sh_output.mode = SH_FAULT;
    sh_output.q_bi.w = 1.0;
    sh_output.q_bi.x = 0.0;
    sh_output.q_bi.y = 0.0;
    sh_output.q_bi.z = 0.0;
    sh_output.relative_step_rad = 0.0;
    return;
}

// 2. Handle Disabled State
if (!sh_input.enable) {
    sh_state.mode = SH_OFF;
    sh_state.dropouts = 0;
    sh_state.last_q_bi.w = 1.0;
    sh_state.last_q_bi.x = 0.0;
    sh_state.last_q_bi.y = 0.0;
    sh_state.last_q_bi.z = 0.0;

    sh_output.mode = SH_OFF;
    sh_output.q_bi.w = 1.0;
    sh_output.q_bi.x = 0.0;
    sh_output.q_bi.y = 0.0;
    sh_output.q_bi.z = 0.0;
    sh_output.relative_step_rad = 0.0;
    return;
}

// 3. Process Sample
adcs_quat_t normalized_q;
int sample_accepted = 0;

if (sh_input.valid && sh_input.q_bi != NULL) {
    adcs_status_t status = adcs_quat_normalize(sh_input.q_bi, &normalized_q);
    if (status == ADCS_OK) {
        sample_accepted = 1;
    }
}

if (sample_accepted) {
    // Align sign with last known attitude
    double dot = normalized_q.w * sh_state.last_q_bi.w +
                 normalized_q.x * sh_state.last_q_bi.x +
                 normalized_q.y * sh_state.last_q_bi.y +
                 normalized_q.z * sh_state.last_q_bi.z;

    adcs_quat_t aligned_q;
    if (dot < 0.0) {
        aligned_q.w = -normalized_q.w;
        aligned_q.x = -normalized_q.x;
        aligned_q.y = -normalized_q.y;
        aligned_q.z = -normalized_q.z;
    } else {
        aligned_q = normalized_q;
    }

    // Calculate relative rotation step in radians
    double abs_dot = fabs(dot);
    if (abs_dot > 1.0) abs_dot = 1.0;
    double relative_step = 2.0 * acos(abs_dot);

    // Update State
    sh_state.mode = SH_TRACK;
    sh_state.dropouts = 0;
    sh_state.last_q_bi = aligned_q;

    // Update Output
    sh_output.mode = SH_TRACK;
    sh_output.q_bi = aligned_q;
    sh_output.relative_step_rad = relative_step;
} else {
    // Rejection
    sh_state.dropouts++;

    // Determine published quaternion: retained history or identity if none
    adcs_quat_t published_q;
    int has_valid_history = (sh_state.last_q_bi.w != 0.0 || 
                             sh_state.last_q_bi.x != 0.0 || 
                             sh_state.last_q_bi.y != 0.0 || 
                             sh_state.last_q_bi.z != 0.0);

    if (has_valid_history) {
        published_q = sh_state.last_q_bi;
    } else {
        published_q.w = 1.0;
        published_q.x = 0.0;
        published_q.y = 0.0;
        published_q.z = 0.0;
    }

    if (sh_state.dropouts > sh_config.max_hold_cycles) {
        sh_state.mode = SH_FAULT;
        sh_output.mode = SH_FAULT;
        sh_output.q_bi = published_q;
        sh_output.relative_step_rad = 0.0;
    } else {
        sh_state.mode = SH_HOLD;
        sh_output.mode = SH_HOLD;
        sh_output.q_bi = published_q;
        sh_output.relative_step_rad = 0.0;
    }
}

